package com.propverse.dao;
import com.propverse.database.DBConnection;import java.sql.*;import java.util.*;
public class RecordDAO {
 public record Spec(String table,String id,String[] columns,String[] labels,String[] searchColumns,String[] filterColumns,String[] filterLabels){}
 public static final Spec PROJECT=new Spec("projects","project_id",new String[]{"project_name","location","client_name","start_date","end_date","budget","status","progress_percentage"},new String[]{"Project name *","Location *","Client","Start date (YYYY-MM-DD)","End date (YYYY-MM-DD)","Budget","Status","Progress %"},new String[]{"project_name","location"},new String[]{"status"},new String[]{"Status"});
 public static final Spec WORKER=new Spec("workers","worker_id",new String[]{"full_name","role","phone","email","project_id","availability_status"},new String[]{"Full name *","Role *","Phone","Email","Primary project","Availability"},new String[]{"full_name","role"},new String[]{"role","project_id","availability_status"},new String[]{"Role","Project","Availability"});
 public static final Spec TASK=new Spec("tasks","task_id",new String[]{"task_name","project_id","assigned_worker_id","start_date","deadline","status","progress_percentage","description"},new String[]{"Task name *","Project *","Assigned worker (optional)","Start date","Deadline","Status","Progress %","Description"},new String[]{"task_name","description"},new String[]{"project_id","status"},new String[]{"Project","Status"});
 public static final Spec ISSUE=new Spec("issues","issue_id",new String[]{"project_id","issue_title","description","priority","status","resolution_notes"},new String[]{"Project *","Issue title *","Description","Priority","Status","Resolution notes"},new String[]{"issue_title","description"},new String[]{"project_id","priority","status"},new String[]{"Project","Priority","Status"});
 public record Choice(String id,String label){public String toString(){return label;}}
 public List<String> distinct(String table,String column)throws SQLException{if(!((table.equals("workers")&&column.equals("role"))))throw new IllegalArgumentException("Unsupported filter");List<String> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery("SELECT DISTINCT role FROM workers ORDER BY role")){while(r.next())out.add(r.getString(1));}return out;}
 public List<Choice> choices(String table)throws SQLException{String sql=switch(table){case "projects"->"SELECT project_id,project_name FROM projects ORDER BY project_name";case "workers"->"SELECT worker_id,full_name FROM workers ORDER BY full_name";default->throw new IllegalArgumentException("Unsupported lookup");};List<Choice> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(sql)){while(r.next())out.add(new Choice(r.getString(1),r.getString(2)+" (#"+r.getString(1)+")"));}return out;}
 public List<Map<String,Object>> all(Spec s,String q)throws SQLException{return all(s,q,Collections.emptyMap());}
 public List<Map<String,Object>> all(Spec s,String q,Map<String,String> filters)throws SQLException{try(Connection c=DBConnection.getConnection()){return all(c,s,q,filters);}}
 public List<Map<String,Object>> all(Connection c,Spec s,String q,Map<String,String> filters)throws SQLException{StringBuilder where=new StringBuilder();List<String> params=new ArrayList<>();if(q!=null&&!q.isBlank()){where.append("(");for(int i=0;i<s.searchColumns.length;i++){if(i>0)where.append(" OR ");where.append(s.searchColumns[i]).append(" LIKE ?");params.add("%"+q.trim()+"%");}where.append(")");}for(String col:s.filterColumns){String value=filters.get(col);if(value!=null&&!value.isBlank()){if(where.length()>0)where.append(" AND ");where.append(col).append("=?");params.add(value);}}String sql="SELECT * FROM "+s.table+(where.length()==0?"":" WHERE "+where)+" ORDER BY "+s.id+" DESC";try(PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<params.size();i++)p.setString(i+1,params.get(i));try(ResultSet r=p.executeQuery()){List<Map<String,Object>> a=new ArrayList<>();ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));a.add(m);}return a;}}}
 public void save(Spec s,Integer id,List<String> v)throws SQLException{try(Connection c=DBConnection.getConnection()){save(c,s,id,v);}}
 public void save(Connection c,Spec s,Integer id,List<String> v)throws SQLException{StringJoiner qs=new StringJoiner(","),sets=new StringJoiner(",");for(String col:s.columns){qs.add("?");sets.add(col+"=?");}String sql=id==null?"INSERT INTO "+s.table+" ("+String.join(",",s.columns)+") VALUES ("+qs+")":"UPDATE "+s.table+" SET "+sets+" WHERE "+s.id+"=?";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;for(String x:v){if(x==null||x.isBlank())p.setNull(i++,Types.VARCHAR);else p.setString(i++,x.trim());}if(id!=null)p.setInt(i,id);p.executeUpdate();}}
 public void delete(Spec s,int id)throws SQLException{try(Connection c=DBConnection.getConnection()){delete(c,s,id);}}
 public void delete(Connection c,Spec s,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM "+s.table+" WHERE "+s.id+"=?")){p.setInt(1,id);p.executeUpdate();}}
 public Map<String,Integer> counts()throws SQLException{String[] names={"Total projects","Ongoing projects","Total workers","Pending tasks","Open issues"},sql={"SELECT COUNT(*) FROM projects","SELECT COUNT(*) FROM projects WHERE status='ONGOING'","SELECT COUNT(*) FROM workers","SELECT COUNT(*) FROM tasks WHERE status<>'COMPLETED'","SELECT COUNT(*) FROM issues WHERE status<>'RESOLVED'"};Map<String,Integer> m=new LinkedHashMap<>();try(Connection c=DBConnection.getConnection()){for(int i=0;i<sql.length;i++)try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql[i])){r.next();m.put(names[i],r.getInt(1));}}return m;}
 public boolean hasProjects()throws SQLException{try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM projects")){r.next();return r.getInt(1)>0;}}
}
